-- SQL twin of DAX measure [Mix Variance (SYNTHETIC)] (table fact_actual_month_SYNTHETIC); context: site S1, months closed; DuckDB over exports/*.csv
with b as (select item_key, sum(admins) bi, sum(contribution) bc from fact_plan_month where site_id = 'S1' and month_start <= (select max(month_start) from fact_actual_month_SYNTHETIC) group by 1), a as (select item_key, sum(admins) ai from fact_actual_month_SYNTHETIC where site_id = 'S1' group by 1), t as (select (select sum(bi) from b) ba, (select sum(ai) from a) aa) select sum((coalesce(a.ai, 0) - t.aa * b.bi / t.ba) * b.bc / b.bi) from b left join a using (item_key), t
